<script setup lang="ts">
import { onMounted,ref } from 'vue';
import { get } from '../services/api';
import { useAuth } from '../stores/auth';
import { useUi } from '../stores/ui';
import type { Project,Task } from '../types';
import { dateLabel,overdue } from '../types';
import StatCard from '../components/StatCard.vue';
import ProjectCard from '../components/ProjectCard.vue';
import ProjectDialog from '../components/ProjectDialog.vue';
import EmptyState from '../components/EmptyState.vue';
const auth=useAuth(),ui=useUi(),loading=ref(true),dialog=ref(false);
const stats=ref<{total_projects:number;active_projects:number;assigned_tasks:number;completed_tasks:number;in_progress_tasks:number;overdue_tasks:number;progress:number;recent_projects:Project[];upcoming:Task[]}|null>(null);
async function load(){loading.value=true;try{stats.value=await get('/dashboard/stats');}catch(e){ui.fail(e);}finally{loading.value=false;}}
onMounted(load);
</script>
<template><div class="page-heading"><div><div class="eyebrow">TAVS DARBA PĀRSKATS</div><h1>Sveiki, {{auth.user?.name.split(' ')[0]}} <span class="wave">✦</span></h1><p>Viss svarīgais vienuviet. Sāksim ar nākamo soli.</p></div><v-btn color="primary" prepend-icon="mdi-plus" size="large" @click="dialog=true">Jauns projekts</v-btn></div><v-progress-linear v-if="loading" indeterminate color="primary" aria-label="Ielādē pārskatu"/><template v-else-if="stats"><div class="stats-grid"><StatCard label="Visi projekti" :value="stats.total_projects" icon="mdi-folder-outline" :hint="stats.active_projects+' aktīvi projekti'"/><StatCard to="/tasks" label="Mani uzdevumi" :value="stats.assigned_tasks" icon="mdi-format-list-checks" hint="Tev uzticētie uzdevumi" color="primary"/><StatCard label="Pabeigti uzdevumi" :value="stats.completed_tasks" icon="mdi-check-circle-outline" hint="Solis tuvāk mērķim" color="success"/><StatCard label="Procesā" :value="stats.in_progress_tasks" icon="mdi-progress-clock" :hint="stats.overdue_tasks+' nokavēti uzdevumi'" color="warning"/></div><div class="dashboard-main"><section><div class="section-heading"><h2>Nesenie projekti</h2><v-btn variant="text" color="primary" to="/projects" append-icon="mdi-arrow-right">Visi projekti</v-btn></div><div v-if="stats.recent_projects.length" class="project-grid"><ProjectCard v-for="project in stats.recent_projects" :key="project.id" :project="project"/></div><v-card v-else><EmptyState title="Vieta tavām idejām" description="Izveido pirmo projektu un uzaicini komandu."><v-btn color="primary" class="mt-4" @click="dialog=true">Izveidot projektu</v-btn></EmptyState></v-card><v-card class="overview-banner mt-6"><div><div class="eyebrow">SOLI PA SOLIM</div><h3>Katrs uzdevums veido rezultātu.</h3><p>Tavas komandas projektu kopējais progress.</p></div><v-progress-circular :model-value="stats.progress" :size="94" :width="7" color="primary"><strong>{{stats.progress}}%</strong></v-progress-circular></v-card></section><section><div class="section-heading"><h2>Tuvākie termiņi</h2><v-icon icon="mdi-calendar-month-outline" color="slate"/></div><v-card class="deadline-card"><template v-if="stats.upcoming.length"><router-link v-for="task in stats.upcoming" :key="task.id" :to="'/projects/'+task.project_id" class="deadline-row"><span class="deadline-icon"><v-icon :icon="overdue(task)?'mdi-clock-alert-outline':'mdi-checkbox-blank-circle-outline'" :color="overdue(task)?'error':'primary'" size="21"/></span><div><strong>{{task.title}}</strong><small>{{task.project_name}}</small><span :class="overdue(task)?'text-error':'text-medium-emphasis'">{{dateLabel(task.due_date)}}{{overdue(task)?' · Nokavēts':''}}</span></div><v-icon icon="mdi-chevron-right" color="slate" size="18"/></router-link></template><EmptyState v-else title="Viss mierīgi" description="Nav nepabeigtu uzdevumu ar termiņu." icon="mdi-calendar-check-outline"/></v-card></section></div></template><v-alert v-else type="error" variant="tonal">Pārskatu nevarēja ielādēt.<v-btn variant="text" @click="load">Mēģināt vēlreiz</v-btn></v-alert><ProjectDialog v-model="dialog" @saved="load"/></template>


